// ============================================
// FINAL AGGREGATION — Clean Top Lists
// ============================================

const rows = $input.all().map(i => i.json);

// Keep valid items only (if using validation)
const clean = rows
  .filter(r => r && r.symbol)
  .filter(r => r.valid === undefined ? true : r.valid === true);

// Normalize numbers
const data = clean.map(r => ({
  symbol: r.symbol,
  changePct: Number(r.changePct),
  volumeUSDT: Number(r.volumeUSDT),   // quoteVolume
  tradeCount: Number(r.tradeCount),   // count
}));

// 🔺 TOP 10 GAINERS
const topGainers = [...data]
  .sort((a, b) => b.changePct - a.changePct)
  .slice(0, 10)
  .map(x => ({
    symbol: x.symbol,
    changePct: x.changePct.toFixed(2)
  }));

// 🔻 TOP 10 LOSERS
const topLosers = [...data]
  .sort((a, b) => a.changePct - b.changePct)
  .slice(0, 10)
  .map(x => ({
    symbol: x.symbol,
    changePct: x.changePct.toFixed(2)
  }));

// 💰 TOP 5 VOLUME (volume ONLY)
const topVolume = [...data]
  .sort((a, b) => b.volumeUSDT - a.volumeUSDT)
  .slice(0, 5)
  .map(x => ({
    symbol: x.symbol,
    volumeUSDT: Math.round(x.volumeUSDT)
  }));

// 🔁 TOP 5 TRADES (count ONLY)
const topTrades = [...data]
  .sort((a, b) => b.tradeCount - a.tradeCount)
  .slice(0, 5)
  .map(x => ({
    symbol: x.symbol,
    tradeCount: x.tradeCount
  }));

// Summary
const summary = {
  inputCount: rows.length,
  usedCount: data.length,
  generatedAt: new Date().toISOString(),
};

// Return ONE item
return [{
  json: {
    summary,
    topGainers,
    topLosers,
    topVolume,
    topTrades,
  }
}];

// -------------------------------
// 1) Read AI Agent output safely
// -------------------------------
const aiRaw = $input.first()?.json ?? {};

const maybeText =
  (typeof aiRaw.output === "string" && aiRaw.output) ||
  (typeof aiRaw.text === "string" && aiRaw.text) ||
  (typeof aiRaw.content === "string" && aiRaw.content) ||
  (typeof aiRaw.data?.output === "string" && aiRaw.data.output) ||
  null;

let aiObj = null;

if (maybeText) {
  const cleaned = maybeText
    .trim()
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "");

  try { aiObj = JSON.parse(cleaned); } catch { aiObj = null; }
} else if (Array.isArray(aiRaw.analysis)) {
  aiObj = aiRaw;
}

const analysis = Array.isArray(aiObj?.analysis) ? aiObj.analysis : [];

// -------------------------------
// 2) Get market movers (safe)
// -------------------------------
const marketItems = $items("Code in JavaScript2");
const market = marketItems?.[0]?.json ?? {
  topGainers: [],
  topLosers: [],
  topVolume: [],
  topTrades: []
};

// -------------------------------
// 3) Build a map: asset -> sentiment object
// -------------------------------
const sentimentMap = {};
for (const a of analysis) {
  if (!a || !a.symbol) continue;
  sentimentMap[String(a.symbol).toUpperCase()] = a;
}

function toAsset(sym) {
  return String(sym || "")
    .toUpperCase()
    .replace(/USDT$/, "")
    .trim();
}

function attachSentiment(list, n = 5) {
  return (Array.isArray(list) ? list : []).slice(0, n).map(c => {
    const asset = toAsset(c.symbol);
    const a = sentimentMap[asset];

    return {
      symbol: c.symbol,
      asset,
      changePct: c.changePct,
      sentiment: a?.sentiment || "neutral",
      score: a?.sentimentScore ?? 0,
      reasons: Array.isArray(a?.reasons) ? a.reasons : [],
      keyHeadlines: Array.isArray(a?.keyHeadlines) ? a.keyHeadlines : []
    };
  });
}

return [{
  json: {
    topGainers: (market.topGainers ?? []).slice(0, 10),
    topLosers: (market.topLosers ?? []).slice(0, 10),
    topVolume: (market.topVolume ?? []).slice(0, 5),
    topTrades: (market.topTrades ?? []).slice(0, 5),

    sentiment: {
      gainers: attachSentiment(market.topGainers, 5),
      losers: attachSentiment(market.topLosers, 5)
    },

    _debug: {
      aiParsed: !!aiObj,
      analysisCount: analysis.length,
      exampleAIKeys: Object.keys(sentimentMap).slice(0, 10)
    }
  }
}];

const g = $json.topGainers.slice(0, 5).map(x => x.symbol);
const l = $json.topLosers.slice(0, 5).map(x => x.symbol);

const symbols = [...g, ...l];

return symbols.map(s => ({
  json: { symbol: s }
}));

const grouped = {};
let total = 0;
let kept = 0;
const missingAssetSamples = [];

for (const item of items) {
  total++;
  const j = item.json || {};

  const asset = (j.asset ?? "").toString().trim();
  if (!asset) {
    if (missingAssetSamples.length < 5) {
      missingAssetSamples.push({
        source: j.source,
        title: j.title,
        url: j.url,
        asset: j.asset,
      });
    }
    continue;
  }

  // Optional: filter invalid articles (prevents empty rows)
  const title = (j.title ?? "").toString().trim();
  const url = (j.url ?? "").toString().trim();
  if (!title || !url) continue;

  if (!grouped[asset]) grouped[asset] = [];
  grouped[asset].push({
    source: j.source || "",
    title,
    url,
    publishedAt: j.publishedAt || null,
    summary: (j.summary ?? "").toString(),
  });

  kept++;
}

// limit per asset
for (const k of Object.keys(grouped)) {
  grouped[k] = grouped[k].slice(0, 10);
}

// ✅ Debug info (so you instantly know why it’s empty)
return [
  {
    json: {
      groupedNews: grouped,
      _debug: {
        totalIncomingItems: total,
        keptItems: kept,
        assetCount: Object.keys(grouped).length,
        missingAssetSamples,
      },
    },
  },
];

const coin = $item(0).$node["cointelegraph loop"].json;

return $items()
  .map(i => {
    const j = i.json || {};
    const title = j.title || "";
    const url = j.link || j.url || "";
