// Input items: each item has { symbol, keyword } (keyword = base coin like DENT)
// Output: one item per coin with its own rssUrl + query

const kws = $items().map(i => i.json.keyword).filter(Boolean);
const unique = [...new Set(kws)];

const nameMap = {
  BTC: "Bitcoin",
  ETH: "Ethereum",
  XRP: "XRP",
  SOL: "Solana",
  DOGE: "Dogecoin",
  DOT: "Polkadot",
  UNI: "Uniswap",
  AR: "Arweave",
};

const enc = (s) => encodeURIComponent(s);

return unique.map(asset => {
  const name = nameMap[asset] || asset;

  // robust query: name + ticker + crypto context
  const query = `("${name}" OR "${asset}") (crypto OR token OR blockchain OR exchange OR ETF OR SEC OR lawsuit OR hack OR partnership OR listing OR delisting)`;

  const rssUrl = `https://news.google.com/rss/search?q=${enc(query)}&hl=en-AU&gl=AU&ceid=AU:en`;

  return {
    json: {
      asset,       // e.g. DENT
      name,        // e.g. Dent
      query,
      rssUrl
    }
  };
});

// JS0 — Binance 24hr ticker → candidate list for liquidity check

const data = $input.all().map(i => i.json);

const toNum = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

const MIN_VOLUME_USDT = 1_000_000;
const MIN_TRADES = 1_000;

// Build clean rows
const base = data
  .filter(t => typeof t.symbol === "string" && t.symbol.endsWith("USDT"))
  .filter(t => !/(UP|DOWN|BULL|BEAR)USDT$/.test(t.symbol))
  .map(t => ({
    symbol: t.symbol,
    changePct: toNum(t.priceChangePercent),
    volumeUSDT: toNum(t.quoteVolume),
    tradeCount: toNum(t.count),
    lastPrice: toNum(t.lastPrice),
  }))
  .filter(x => x.volumeUSDT >= MIN_VOLUME_USDT && x.tradeCount >= MIN_TRADES)
  .filter(x => x.lastPrice > 0);

// Rank pools
const topGainersPool = [...base]
  .sort((a,b) => b.changePct - a.changePct)
  .slice(0, 50);

const topLosersPool  = [...base]
  .sort((a,b) => a.changePct - b.changePct)
  .slice(0, 50);

// Combine & dedupe
const map = new Map();
for (const r of [...topGainersPool, ...topLosersPool]) {
  map.set(r.symbol, r);
}

let moversForLoop = [...map.values()];

// 🔥 REDUCE HERE (before return)
moversForLoop = moversForLoop
  .sort((a,b) => b.volumeUSDT - a.volumeUSDT)  // most liquid first
  .slice(0, 60);                               // keep only 60

// Final output to Loop Over Items
return moversForLoop.map(m => ({ json: m }));

// ============================================
// JavaScript1 — Market Quality Metrics (LOOP SAFE + correct symbol)
// ============================================

// ✅ Get current loop item (the mover) correctly
const base = $item(0).$node["Loop Over Items"].json;
const symbol = base.symbol;

// ✅ Depth response from HTTP Request1
const bids = $json.bids || [];
const asks = $json.asks || [];

// best bid/ask
const bestBid = parseFloat(bids[0]?.[0] || 0);
const bestAsk = parseFloat(asks[0]?.[0] || 0);

const spread = bestAsk - bestBid;
const midPrice = (bestAsk + bestBid) / 2;
const spreadPct = midPrice > 0 ? (spread / midPrice) * 100 : 0;

function depthWithinPercent(orders, anchorPrice, percent, isBidSide) {
  if (!Array.isArray(orders) || orders.length === 0 || anchorPrice <= 0) return 0;

  const threshold = isBidSide
    ? anchorPrice * (1 - percent)
    : anchorPrice * (1 + percent);

  let totalQuote = 0;

  for (const level of orders) {
    const priceLevel = parseFloat(level?.[0] || 0);
    const qty = parseFloat(level?.[1] || 0);
    if (priceLevel <= 0 || qty <= 0) continue;

    if (isBidSide) {
      if (priceLevel >= threshold) totalQuote += priceLevel * qty;
      else break;
    } else {
      if (priceLevel <= threshold) totalQuote += priceLevel * qty;
      else break;
    }
  }

  return totalQuote;
}

const depth1pctUSDT =
  depthWithinPercent(bids, bestBid, 0.01, true) +
  depthWithinPercent(asks, bestAsk, 0.01, false);

const depth2pctUSDT =
  depthWithinPercent(bids, bestBid, 0.02, true) +
  depthWithinPercent(asks, bestAsk, 0.02, false);

// thresholds (tune)
const MAX_SPREAD_PCT = 1.5;
const MIN_DEPTH_1PCT = 5000;
const MIN_DEPTH_2PCT = 10000;

const isInvalid =
  !symbol ||
  bids.length === 0 ||
  asks.length === 0 ||
  bestBid <= 0 ||
  bestAsk <= 0 ||
  spread <= 0 ||
  !Number.isFinite(spreadPct) ||
  spreadPct <= 0 ||
  depth1pctUSDT <= 0 ||
  depth2pctUSDT <= 0;

const failsQuality =
  spreadPct > MAX_SPREAD_PCT ||
  depth1pctUSDT < MIN_DEPTH_1PCT ||
  depth2pctUSDT < MIN_DEPTH_2PCT;

const valid = !(isInvalid || failsQuality);

return [
  {
    json: {
      ...base, // includes changePct, volumeUSDT, tradeCount etc
      symbol,
      bestBid,
      bestAsk,
      spread,
      spreadPct,
      depth1pctUSDT,
      depth2pctUSDT,
      valid,
      reason: valid ? null : (isInvalid ? "invalid_orderbook" : "fails_quality"),
      checkedAt: new Date().toISOString(),
    },
  },
];

const assets = $items()
  .map(i => i.json.asset)
  .filter(Boolean);

const unique = [...new Set(assets)];

const nameMap = {
  BTC: "Bitcoin",
  ETH: "Ethereum",
  XRP: "XRP",
  SOL: "Solana",
  DOGE: "Dogecoin",
  DOT: "Polkadot",
  UNI: "Uniswap",
  AR: "Arweave",
};

const enc = (s) => encodeURIComponent(s);

return unique.map(asset => {
  const name = nameMap[asset] || asset;

  const query = `("${name}" OR "${asset}") (crypto OR token OR blockchain OR exchange OR ETF OR SEC OR lawsuit OR hack OR partnership OR listing OR delisting)`;

  const rssUrl = `https://news.google.com/rss/search?q=${enc(query)}&hl=en-AU&gl=AU&ceid=AU:en`;

  return {
    json: { asset, name, query, rssUrl }
  };
});

// ✅ Always use the CURRENT item from the loop node
const coin = $item(0).$node["Google rss loop"].json;

return $items().map(i => ({
  json: {
    asset: coin.asset,
    name: coin.name,
    source: "GoogleNews",

    title: i.json.title,
    url: i.json.link,
    publishedAt: i.json.pubDate || i.json.isoDate || null,
    summary: i.json.contentSnippet || i.json.content || i.json.description || ""
  }
}));

const assets = $items().map(i => i.json.asset).filter(Boolean);
const unique = [...new Set(assets)];

return unique.map(asset => ({
  json: {
    asset,
    name: asset,
    source: "Cointelegraph",
    rssUrl: "https://cointelegraph.com/rss"
  }
}));

// CoinDesk: use global RSS, then filter per coin later in Normalize
const assets = $items().map(i => i.json.asset || i.json.keyword).filter(Boolean);
const unique = [...new Set(assets)];

const nameMap = {
  BTC: "Bitcoin",
  ETH: "Ethereum",
  XRP: "XRP",
  SOL: "Solana",
  DOGE: "Dogecoin",
  DOT: "Polkadot",
  UNI: "Uniswap",
  AR: "Arweave",
};

const rssUrlGlobal = "https://www.coindesk.com/arc/outboundfeeds/rss/";

return unique.map(asset => {
  const name = nameMap[asset] || asset;
  const query = `${name} OR ${asset}`;

  return {
    json: {
      asset,
      name,
      source: "CoinDesk",
      query,
      rssUrl: rssUrlGlobal
    }
  };
});

const grouped = $json.groupedNews || {};

const MAX_ASSETS = 5;          // analyze only top N assets
const MAX_ARTICLES = 3;        // keep only top N articles per asset
const MAX_SUMMARY_LEN = 220;   // cut long summaries

const assets = Object.keys(grouped).slice(0, MAX_ASSETS);

const slim = {};
for (const asset of assets) {
  slim[asset] = (grouped[asset] || [])
    .slice(0, MAX_ARTICLES)
    .map(a => ({
      source: a.source,
      title: a.title,
      url: a.url,
      publishedAt: a.publishedAt,
      summary: (a.summary || "").slice(0, MAX_SUMMARY_LEN),
    }));
}

return [{ json: { groupedNews: slim, _debug: { assetsKept: assets.length, maxArticles: MAX_ARTICLES } } }];
